"use client"; // <- important
import { useSearchParams } from "next/navigation";
import { productMockData } from "@/mockData/mockdata";

const ProductDetailsPage = () => {
  const searchParams = useSearchParams();
  const id = searchParams.get("q"); // get the product id from query
  const product = productMockData.find(p => p.id === parseInt(id));

  if (!product) return <div>Product not found</div>;

  return (
    <div className="p-4">
      <h1 className="text-xl font-bold">{product.name}</h1>
      <img src={product.image} alt={product.name} />
      <p>Price: Rs. {product.price}</p>
      <p>Discount: {product.discount}%</p>
      <p>Rating: {product.rating} ({product.totalRatings} reviews)</p>
    </div>
  );
};

export default ProductDetailsPage;
